begin read only;
select '49ea9aaa-1c46-51e7-b148-a03aef20ae4e public mapping' check_name,((select count(*) from jsonb_array_elements(math_private.release_catalog('324dbf82-b4bc-5607-977b-2cf512812212')) x where x->>'leaf_id'='645d7b6a-2c7a-5a0e-9d34-0eead5c142e5' and x->>'essay_question_id'='49ea9aaa-1c46-51e7-b148-a03aef20ae4e')=1) passed
union all
select '49ea9aaa-1c46-51e7-b148-a03aef20ae4e profile' check_name,((with candidates as(select ep.id,case ep.scope when 'LEAF' then 4 when 'PROBLEM' then 3 when 'EXAM' then 2 else 1 end rank from public.math_subproblems l join public.math_problems pr on pr.id=l.problem_id join public.math_problem_sets ps on ps.id=pr.problem_set_id join public.math_evaluation_profiles ep on ep.state='ACTIVE' and ep.response_format=l.response_format and (ep.leaf_id=l.id or ep.problem_id=l.problem_id or ep.essay_exam_id=ps.essay_exam_id or (ep.scope='COMMON_MATH_RUBRIC' and l.allow_common_rubric)) where l.id='645d7b6a-2c7a-5a0e-9d34-0eead5c142e5' and pr.state='ACTIVE' and ps.state='ACTIVE') select count(*)=1 and bool_and(id='4390a320-b8e7-55f9-9187-535ec9c0ed78'::uuid) from candidates where rank=(select max(rank) from candidates))) passed
union all
select '49ea9aaa-1c46-51e7-b148-a03aef20ae4e Worker evidence' check_name,(exists(select 1 from public.math_subproblems l join public.math_problems pr on pr.id=l.problem_id where l.id='645d7b6a-2c7a-5a0e-9d34-0eead5c142e5' and jsonb_array_length(math_private.hanyang_worker_references(jsonb_build_object('leaf',to_jsonb(l),'problem',to_jsonb(pr),'sources',(select jsonb_agg(to_jsonb(s)) from public.math_source_artifacts s where s.problem_id=pr.id)))->'official_images')>0)) passed;
commit;
